const $=s=>document.querySelector(s),key='careerflow-v1';
const defaults={jobs:[],profile:{name:'Mariana Viana Ferreira',email:'marianaviana121@gmail.com',summary:'',cv:''},rules:{keywords:'DevOps, Cloud, SRE, Azure, Kubernetes',remote:true,auto:true,template:'Olá, equipe de recrutamento da {empresa}!\n\nTenho interesse na oportunidade de {cargo}.\n{resumo}\n\nFico à disposição para conversar.\n{nome}\n{email}'}};
let state=structuredClone(defaults),current=null;try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.jobs))state={...defaults,...saved,profile:{...defaults.profile,...saved.profile},rules:{...defaults.rules,...saved.rules}}}catch{};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{toast('Stockage indisponível: exporte um backup antes de sair.');return false}}
function safeUrl(v){try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function canonical(v){let u=new URL(v);u.hash='';['utm_source','utm_medium','utm_campaign','utm_content','utm_term','trk','trackingId','refId'].forEach(k=>u.searchParams.delete(k));u.searchParams.sort();return u.href.replace(/\/$/,'')}
function score(j){let words=state.rules.keywords.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean),text=(j.role+' '+j.description).toLowerCase();return words.filter(w=>text.includes(w)).length+(state.rules.remote&&j.mode==='Remoto'?1:0)}
function message(j){let p=state.profile,dict={nome:p.name,email:p.email,resumo:p.summary,cargo:j.role,empresa:j.company};return state.rules.template.replace(/\{(nome|email|resumo|cargo|empresa)\}/g,(_,k)=>dict[k])+(p.cv?'\n\nCurrículo: '+p.cv:'')}
const labels={dashboard:['Visão geral','Sua carreira, em movimento.','Organize suas oportunidades. Foque no que vem depois.'],jobs:['Minhas candidaturas','Cada oportunidade, um novo caminho.','Todas as suas candidaturas em um só lugar.'],rules:['Automações','Sua rotina, com menos repetição.','Configure a preparação das suas candidaturas.'],profile:['Perfil e currículo','Sua história abre portas.','Mantenha seus dados prontos para o próximo contato.']};
function view(v){for(const id of ['dashboard','jobs','bottom','rules','profile'])$('#'+id).hidden=!(v==='dashboard'?['dashboard','jobs','bottom'].includes(id):id===v);$('h1').textContent=labels[v][1];$('#subtitle').textContent=labels[v][2];$('#pageLabel').textContent=labels[v][0];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#addTop').hidden=!['dashboard','jobs'].includes(v);if(v==='rules'||v==='profile'){let f=$('#'+v+'Form');for(let [k,val] of Object.entries(state[v]))if(f.elements[k])f.elements[k].type==='checkbox'?f.elements[k].checked=val:f.elements[k].value=val}window.scrollTo(0,0)}
function render(){let jobs=state.jobs;$('#sTotal').textContent=jobs.length;$('#sPrep').textContent=jobs.filter(j=>j.status==='Salva').length;$('#sSent').textContent=jobs.filter(j=>['Enviada','Entrevista'].includes(j.status)).length;$('#sInterview').textContent=jobs.filter(j=>j.status==='Entrevista').length;$('#count').textContent=jobs.length;$('#navCount').textContent=jobs.length;let q=$('#search').value.toLowerCase(),list=jobs.filter(j=>(j.role+' '+j.company).toLowerCase().includes(q)&&(!$('#statusFilter').value||j.status===$('#statusFilter').value)&&(!$('#modeFilter').value||j.mode===$('#modeFilter').value)).sort((a,b)=>score(b)-score(a));$('#jobList').innerHTML=list.length?list.map(j=>`<div class="job-row"><div class="company-icon">${esc(j.company.charAt(0).toUpperCase())}</div><div class="job-info"><strong>${esc(j.role)}</strong><small>${esc(j.company)} · ${esc(j.mode)}</small></div><span class="badge" title="Pontos por palavra-chave e modalidade; não é avaliação de qualificação">${score(j)} pontos de prioridade</span><span class="badge">${esc(j.status)}</span><button class="text-btn" data-detail="${esc(j.id)}">Ver detalhes ↗</button></div>`).join(''):`<div class="empty"><div class="empty-icon">▤</div><h3>${jobs.length?'Nenhuma vaga com esses filtros':'Seu próximo passo começa com uma vaga'}</h3><p>${jobs.length?'Tente outro cargo, empresa ou status.':'Adicione uma oportunidade para organizar sua candidatura.<br>As vagas reais que você salvar aparecerão aqui.'}</p>${jobs.length?'':'<button class="secondary" id="emptyAdd">＋ Adicionar primeira vaga</button>'}</div>`;$('#emptyAdd')?.addEventListener('click',openAdd);document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail))}
function openAdd(){$('#jobForm').reset();$('#jobDialog').showModal()}
function detail(id){current=id;let j=state.jobs.find(j=>j.id===id);$('#detailTitle').textContent=j.role;$('#detailBody').innerHTML=`<div class="details-meta">${esc(j.company)} · ${esc(j.mode)} · Salva em ${new Date(j.created).toLocaleDateString('pt-BR')}<br>${score(j)} pontos de prioridade pelas suas regras</div><p class="detail-text">${esc(j.description||'Nenhuma descrição adicionada.')}</p><p class="detail-text">${esc(j.notes)}</p><div class="details-actions"><a class="primary" href="${esc(safeUrl(j.url))}" target="_blank" rel="noopener">Abrir vaga ↗</a><button class="secondary" id="prepare">Gerar mensagem</button></div><label>Status<select id="jobStatus">${['Salva','Preparada','Enviada','Entrevista','Encerrada'].map(s=>`<option ${s===j.status?'selected':''}>${s}</option>`).join('')}</select><small>Marque “Enviada” apenas após concluir o envio na plataforma.</small></label><label>Mensagem de apresentação<textarea id="draft" rows="8" placeholder="Clique em gerar mensagem">${esc(j.draft||'')}</textarea></label><div class="details-actions"><button class="secondary" id="copy">Copiar mensagem</button><button class="primary" id="saveDetail">Salvar alterações</button><button class="text-btn danger" id="delete">Excluir vaga</button></div><small>Revise a mensagem antes de usar. Nenhuma candidatura será enviada por este site.</small>`;$('#prepare').onclick=()=>{$('#draft').value=message(j);if($('#jobStatus').value==='Salva')$('#jobStatus').value='Preparada'};$('#saveDetail').onclick=()=>{j.draft=$('#draft').value;j.status=$('#jobStatus').value;save();render();toast('Alterações salvas');$('#detailDialog').close()};$('#copy').onclick=async()=>{if(!$('#draft').value)return toast('Gere uma mensagem primeiro');try{await navigator.clipboard.writeText($('#draft').value);toast('Mensagem copiada')}catch{$('#draft').select();toast('Selecione e copie a mensagem com Ctrl+C')}};$('#delete').onclick=()=>{if(confirm('Excluir esta vaga do seu radar?')){state.jobs=state.jobs.filter(x=>x.id!==id);save();render();$('#detailDialog').close();toast('Vaga excluída')}};if(!$('#detailDialog').open)$('#detailDialog').showModal()}
$('#jobForm').onsubmit=e=>{e.preventDefault();let j=Object.fromEntries(new FormData(e.target));j.role=j.role.trim();j.company=j.company.trim();if(!j.role||!j.company)return toast('Preencha o cargo e a empresa');if(!safeUrl(j.url))return toast('Informe um link HTTP ou HTTPS válido');if(state.jobs.some(x=>canonical(x.url)===canonical(j.url)))return toast('Essa vaga já está no seu radar');Object.assign(j,{id:crypto.randomUUID(),created:new Date().toISOString(),status:'Salva',draft:''});if(state.rules.auto){j.draft=message(j);j.status='Preparada'}state.jobs.push(j);save();render();$('#jobDialog').close();toast('Vaga adicionada ao radar')};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#addTop').onclick=openAdd;$('#setup').onclick=$('#rulesLink').onclick=()=>view('rules');['search','statusFilter','modeFilter'].forEach(id=>$('#'+id).addEventListener('input',render));
$('#rulesForm').onsubmit=e=>{e.preventDefault();let f=e.target;state.rules={keywords:f.elements.keywords.value,remote:f.elements.remote.checked,auto:f.elements.auto.checked,template:f.elements.template.value};save();render();toast('Regras salvas. Aplicadas às próximas preparações.')};
$('#profileForm').onsubmit=e=>{e.preventDefault();let p=Object.fromEntries(new FormData(e.target));if(p.cv&&!safeUrl(p.cv))return toast('Informe um link de currículo HTTP ou HTTPS válido');state.profile=p;save();toast('Perfil salvo')};
function download(content,type,name){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('#export').onclick=()=>{if(!state.jobs.length)return toast('Adicione uma vaga antes de exportar');let rows=[['Cargo','Empresa','Modalidade','Status','Link','Prioridade','Data','Observações'],...state.jobs.map(j=>[j.role,j.company,j.mode,j.status,j.url,score(j),j.created,j.notes])];download('\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8','candidaturas.csv');toast('CSV exportado')};
$('#backup').onclick=()=>download(JSON.stringify(state,null,2),'application/json','careerflow-backup.json');$('#restore').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error();let data=JSON.parse(await file.text());if(!Array.isArray(data.jobs)||!data.profile||!data.rules||data.jobs.some(j=>!j.id||!j.role||!j.company||!safeUrl(j.url)||!['Salva','Preparada','Enviada','Entrevista','Encerrada'].includes(j.status))||['name','email','summary','cv'].some(k=>typeof data.profile[k]!=='string')||typeof data.rules.template!=='string'||typeof data.rules.keywords!=='string')throw Error();if(!confirm('Restaurar este backup e substituir os dados atuais?'))return;state=data;save();render();view('profile');toast('Backup restaurado')}catch{toast('Backup inválido. Use um arquivo exportado pelo CareerFlow.')}finally{e.target.value=''}};render();
